UPDATE TB_DATA_MODEL_OBJ
   SET


       STND_DIAG_TARGET_YN     = #{targetYn},
       STND_DIAG_TARGET_REASON = #{reason}


       STRUCT_DIAG_TARGET_YN     = #{targetYn},
       STRUCT_DIAG_TARGET_REASON = #{reason}


       QUAL_DIAG_TARGET_YN     = #{targetYn},
       QUAL_DIAG_TARGET_REASON = #{reason}


   , DIAG_TARGET_UPDT_USER_ID = #{userId}
   , DIAG_TARGET_UPDT_DT      = to_char(now(),'YYYYMMDDHH24MISS')
 WHERE DM_ID     = #{dmId}
   AND OBJ_OWNER = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
   AND OBJ_NM    = #{objNm}

